"use client";

import { useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { motionTokens } from "@/lib/motion-tokens";
import { photo } from "@/lib/media";
import styles from "./project-folder.module.css";

export interface ProjectFile {
  /** File name, printed at the top of its sheet. */
  name: string;
  /** What the little sheet shows: lines of text, a bar chart, or a picture. */
  kind?: "text" | "chart" | "image";
  /** Picture for `image` sheets. */
  image?: string;
}

export interface ProjectFolderProps {
  /** Folder name, shown under it. */
  name: string;
  /** Short line under the name while the folder is closed, such as "12 files, edited 2h ago". */
  meta?: string;
  /** Files in the folder. The first three peek out; the rest are counted. */
  files?: ProjectFile[];
  /** `accent` fills the folder with the accent color; `neutral` keeps it quiet. */
  tone?: "accent" | "neutral";
  /** Whether the folder is open. Pass it with `onOpenChange` to control it. */
  open?: boolean;
  /** Whether the folder starts open when uncontrolled. */
  defaultOpen?: boolean;
  /** Called when a click or key press opens or closes the folder. */
  onOpenChange?: (open: boolean) => void;
  /** Extra class for the folder button. */
  className?: string;
}

/** How far each sheet travels, in percent of its own size, for the closed, peeking (hover) and open states. */
const POSES = {
  closed: [{ x: "-4%", y: "0%", rotate: -2 }, { x: "0%", y: "0%", rotate: 0 }, { x: "4%", y: "0%", rotate: 2 }],
  peek: [{ x: "-16%", y: "-20%", rotate: -7 }, { x: "0%", y: "-30%", rotate: 0 }, { x: "16%", y: "-20%", rotate: 7 }],
  open: [{ x: "-62%", y: "-46%", rotate: -14 }, { x: "0%", y: "-66%", rotate: 0 }, { x: "62%", y: "-46%", rotate: 14 }],
} as const;
const FLAP = { closed: 0, peek: -24, open: -42 } as const;
const BARS = [46, 72, 58, 88];

function Sheet({ file }: { file: ProjectFile }) {
  const kind = file.kind ?? "text";
  return (
    <span className={styles.paper} data-kind={kind}>
      <span className={styles.paperTitle}>{file.name}</span>
      {kind === "image" ? <img className={styles.picture} src={file.image ?? photo("mountain-ridges").src} alt="" draggable={false} /> : null}
      {kind === "chart" ? <span className={styles.bars}>{BARS.map((height, index) => <span key={index} style={{ height: `${height}%` }} />)}</span> : null}
      {kind === "text" ? <span className={styles.lines}><span /><span /><span /><span /><span /></span> : <span className={styles.lines}><span /><span /></span>}
    </span>
  );
}

/** A folder whose flap leans open on hover and whose sheets rise and fan out on click. */
export function ProjectFolder({ name, meta, files = [], tone = "neutral", open, defaultOpen = false, onOpenChange, className }: ProjectFolderProps) {
  const reduceMotion = useReducedMotion();
  const [internal, setInternal] = useState(defaultOpen);
  const [hovered, setHovered] = useState(false);
  const isOpen = open ?? internal;
  const pose = isOpen ? "open" : hovered ? "peek" : "closed";
  const sheets = files.slice(0, 3);
  const extra = files.length - sheets.length;
  const names = `${sheets.map(file => file.name).join(", ")}${extra > 0 ? ` and ${extra} more` : ""}`;
  const toggle = () => { if (open === undefined) setInternal(!isOpen); onOpenChange?.(!isOpen); };
  // The fan is a little springy; the flap is heavier and settles without bounce.
  const fan = reduceMotion ? { duration: 0 } : { type: "spring" as const, visualDuration: 0.42, bounce: 0.28 };

  return (
    <button
      type="button"
      className={[styles.folder, className].filter(Boolean).join(" ")}
      data-tone={tone}
      data-pose={pose}
      aria-expanded={isOpen}
      onClick={toggle}
      onPointerEnter={event => { if (event.pointerType === "mouse") setHovered(true); }}
      onPointerLeave={() => setHovered(false)}
      onFocus={event => { if (event.currentTarget.matches(":focus-visible")) setHovered(true); }}
      onBlur={() => setHovered(false)}
    >
      <span className={styles.shape} aria-hidden="true">
        <span className={styles.tab} />
        <span className={styles.back} />
        {sheets.map((file, index) => {
          // Two sheets take the outer poses; one sheet takes the middle.
          const slot = sheets.length === 1 ? 1 : sheets.length === 2 ? index * 2 : index;
          return (
            <motion.span key={file.name} className={styles.sheet} style={{ zIndex: slot === 1 ? 2 : 1 }} initial={false} animate={POSES[pose][slot]} transition={{ ...fan, delay: reduceMotion ? 0 : (pose === "closed" ? sheets.length - 1 - index : index) * 0.045 }}>
              <Sheet file={file} />
            </motion.span>
          );
        })}
        <motion.span className={styles.flap} initial={false} animate={{ rotateX: reduceMotion ? 0 : FLAP[pose] }} transition={reduceMotion ? { duration: 0 } : motionTokens.spring.gentle}>
          {files.length ? <span className={styles.badge}>{files.length}</span> : null}
        </motion.span>
      </span>
      <span className={styles.name}>{name}</span>
      <span className={styles.meta}>
        <AnimatePresence mode="wait" initial={false}>
          <motion.span key={isOpen ? "files" : "meta"} className={styles.metaLine} initial={reduceMotion ? { opacity: 0 } : { opacity: 0, y: 6 }} animate={{ opacity: 1, y: 0 }} exit={reduceMotion ? { opacity: 0 } : { opacity: 0, y: -6 }} transition={{ duration: motionTokens.duration.fast, ease: motionTokens.ease.standard }}>
            {isOpen && names ? names : meta ?? `${files.length} files`}
          </motion.span>
        </AnimatePresence>
      </span>
    </button>
  );
}

const PROJECTS: { name: string; meta: string; tone: "accent" | "neutral"; files: ProjectFile[] }[] = [
  { name: "Brand refresh", meta: "12 files, edited 2h ago", tone: "accent", files: [{ name: "Moodboard", kind: "image", image: photo("terracotta-waves").src }, { name: "Launch brief" }, { name: "Reach by week", kind: "chart" }, ...Array.from({ length: 9 }, (_, index) => ({ name: `Draft ${index + 1}` }))] },
  { name: "Q4 planning", meta: "7 files, edited yesterday", tone: "neutral", files: [{ name: "Roadmap" }, { name: "Budget", kind: "chart" }, { name: "Offsite", kind: "image", image: photo("alpine-lake").src }, ...Array.from({ length: 4 }, (_, index) => ({ name: `Notes ${index + 1}` }))] },
  { name: "Client contracts", meta: "4 files, edited Monday", tone: "neutral", files: [{ name: "Northwind MSA" }, { name: "Renewal terms" }, { name: "Invoices", kind: "chart" }, { name: "Signed copy" }] },
];

/** Ready preview: three project folders; opening one closes the others. */
export function ProjectFolderPreview() {
  const [open, setOpen] = useState<string | null>(null);
  return (
    <section className={styles.preview} aria-label="Projects">
      <div className={styles.shelf}>
        {PROJECTS.map(project => (
          <ProjectFolder key={project.name} {...project} open={open === project.name} onOpenChange={next => setOpen(next ? project.name : null)} />
        ))}
      </div>
      <p className={styles.hint}>Hover a folder to let its files peek out; click to spread them.</p>
    </section>
  );
}

export default ProjectFolderPreview;

/* The folder scales from one length: set --folder-size on it or on a parent. */
.folder {
  --size: var(--folder-size, 13rem);
  --back: color-mix(in oklab, var(--foreground) 24%, var(--background));
  --front: color-mix(in oklab, var(--foreground) 13%, var(--background));
  --front-ink: var(--text-secondary);
  display: grid; width: var(--size); justify-items: center; gap: 2px; padding: 0; border: 0; border-radius: var(--radius-control); background: transparent; color: var(--foreground); font: inherit; font-family: var(--font-body); letter-spacing: var(--tracking-body); text-align: center; cursor: pointer; -webkit-tap-highlight-color: transparent;
}
.folder *, .folder *::before, .folder *::after { box-sizing: border-box; }
.folder[data-tone="accent"] { --back: color-mix(in oklab, var(--accent) 70%, var(--accent-foreground)); --front: var(--accent); --front-ink: var(--accent-foreground); }

/* Room above the folder for the sheets to rise into. */
.shape { position: relative; display: block; width: 100%; aspect-ratio: 4 / 3; margin: calc(var(--size) * .36) 0 var(--space-3); perspective: 700px; }
.tab { position: absolute; top: 0; left: 0; width: 42%; height: 24%; border-radius: calc(var(--size) * .07) calc(var(--size) * .07) 0 0; background: var(--back); }
.back { position: absolute; inset: 13% 0 0; border-radius: 0 calc(var(--size) * .08) calc(var(--size) * .08) calc(var(--size) * .08); background: var(--back); }

/* Sheets stand inside the folder and move with transforms only. Percentages in the poses are relative to the sheet itself. */
.sheet { position: absolute; bottom: 8%; left: 27%; display: block; width: 46%; aspect-ratio: 3 / 4; transform-origin: 50% 100%; will-change: transform; }
/* Paper keeps its own light palette in both themes: a document is white whatever the interface around it. */
.paper { display: flex; width: 100%; height: 100%; flex-direction: column; gap: 6%; overflow: hidden; padding: 10% 10% 0; border: 1px solid var(--neutral-4); border-radius: calc(var(--size) * .035); background: var(--neutral-1); box-shadow: var(--shadow-raised); color: var(--neutral-10); text-align: start; }
.paperTitle { overflow: hidden; font-size: calc(var(--size) * .042); font-weight: 600; line-height: 1.2; text-overflow: ellipsis; white-space: nowrap; }
.lines { display: grid; gap: calc(var(--size) * .022); }
.lines span { height: calc(var(--size) * .016); border-radius: var(--radius-pill); background: var(--neutral-4); }
.lines span:nth-child(2) { width: 82%; }
.lines span:nth-child(3) { width: 94%; }
.lines span:nth-child(4) { width: 64%; }
.lines span:nth-child(5) { width: 76%; }
.picture { width: 100%; aspect-ratio: 4 / 3; border-radius: calc(var(--size) * .02); object-fit: cover; }
.bars { display: flex; height: 38%; align-items: flex-end; gap: 8%; padding-bottom: 4%; border-bottom: 1px solid var(--neutral-4); }
.bars span { flex: 1 1 0; border-radius: 2px 2px 0 0; background: var(--neutral-5); }
.bars span:last-child { background: var(--neutral-10); }

.flap { position: absolute; inset: 30% 0 0; z-index: 3; display: block; border-radius: calc(var(--size) * .08); background: var(--front); box-shadow: inset 0 1px 0 color-mix(in oklab, var(--front-ink) 16%, transparent), 0 -1px 3px color-mix(in oklab, var(--neutral-11) 12%, transparent); transform-origin: 50% 100%; will-change: transform; }
.badge { position: absolute; right: 8%; bottom: 12%; display: grid; min-width: 1.75em; height: 1.75em; place-items: center; padding: 0 .5em; border-radius: var(--radius-pill); background: color-mix(in oklab, var(--front-ink) 12%, transparent); color: var(--front-ink); font-size: var(--text-xs); font-weight: 600; font-variant-numeric: tabular-nums; }

.name { font-size: var(--text-sm); font-weight: 600; line-height: 1.35; }
.meta { display: block; width: 100%; min-height: 2.7em; color: var(--text-muted); font-size: var(--text-xs); line-height: 1.35; }
.metaLine { display: block; text-wrap: balance; }

.preview { display: flex; min-height: 560px; flex: 1 1 auto; flex-direction: column; align-items: center; justify-content: center; gap: var(--space-8); padding: var(--space-8) var(--space-4); background: var(--background); }
.shelf { display: flex; flex-wrap: wrap; align-items: flex-start; justify-content: center; gap: var(--space-6) var(--space-16); }
.hint { margin: 0; color: var(--text-muted); font-family: var(--font-body); font-size: var(--text-xs); text-align: center; }
@media (max-width: 52rem) { .shelf { gap: var(--space-4) var(--space-10); --folder-size: 10rem; } }
@media (max-width: 30rem) { .shelf { gap: var(--space-2) var(--space-12); --folder-size: 7.5rem; } }

/**
 * Shared demo media. Files live in `public/media/` and are generated by `scripts/make-media.mjs`:
 * people are seeded gradient avatars (400 px squares), photos are abstract generated scenes. No third-party images.
 *
 * Paths start at `/media`. An app served from a subfolder sets `globalThis.__RYAN_UI_MEDIA__` (for example to
 * "./media") before the components load.
 */
const mediaRoot = ((globalThis as { __RYAN_UI_MEDIA__?: string }).__RYAN_UI_MEDIA__ ?? "/media").replace(/\/$/, "");

/** Resolves a path inside the media folder, such as `mediaUrl("people/emma-collins.svg")`. */
export const mediaUrl = (path: string) => `${mediaRoot}/${path.replace(/^\//, "")}`;

export interface MediaPerson {
  id: string;
  name: string;
  role?: string;
  src: string;
}

export interface MediaPhoto {
  id: string;
  alt: string;
  src: string;
  width: number;
  height: number;
}

